import { useState } from 'react';
import { Box, Tabs, Tab, Typography, Grid } from '@mui/material';
import { useTheme, styled } from '@mui/material/styles';
import TabSection1 from '../sections/TabSection1';

const SimpleTab = ({ tabsData, imageShow }) => {
    const theme = useTheme();
    const [value, setValue] = useState(0);

    const handleChange = (event, newValue) => {
        setValue(newValue);
    };

    return (
        <>
            <Grid container justifyContent="center" sx={{ background: theme.palette.text.primary, py: 3, marginTop: '-4rem' }}>
                <Grid item xs={12}>
                    {/* Mobile View - Full Width Tabs */}
                    <Box sx={{ display: { xs: 'flex', md: 'none' }, flexWrap: 'wrap', gap: 1, justifyContent: 'center' }}>
                        {tabsData.map((tab, index) => (
                            <Box
                                key={index}
                                onClick={() => setValue(index)}
                                sx={{
                                    minWidth: { xs: 'calc(50% - 8px)', sm: 'auto' },
                                    padding: { xs: '8px 12px', sm: '14px 16px' },
                                    borderRadius: '4px',
                                    border: `2px solid ${theme.palette.secondary.dark}`,
                                    backgroundColor: value === index ? theme.palette.text.primary : theme.palette.secondary.dark,
                                    cursor: 'pointer',
                                    '&:hover': {
                                        backgroundColor: theme.palette.text.primary,
                                        '& .MuiBox-root': {
                                            color: theme.palette.secondary.dark
                                        }
                                    }
                                }}
                            >
                                <Box
                                    sx={{
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: '8px',
                                        color: value === index ? theme.palette.primary.main : theme.palette.common.white,
                                        transition: 'all 0.3s ease'
                                    }}
                                >
                                    <Box
                                        sx={{
                                            fontSize: { xs: '1.25rem', sm: '1.5rem' },
                                            display: 'flex',
                                            alignItems: 'center'
                                        }}
                                    >
                                        {tab.icon}
                                    </Box>
                                    <Typography
                                        variant="body1"
                                        fontWeight={600}
                                        noWrap
                                        sx={{
                                            fontSize: { xs: '0.75rem', sm: '0.875rem', md: '1rem' },
                                            display: 'inline-block',
                                            maxWidth: '100%',
                                            overflow: 'hidden',
                                            textOverflow: 'ellipsis'
                                        }}
                                    >
                                        {tab.label}
                                    </Typography>
                                </Box>
                            </Box>
                        ))}
                    </Box>

                    {/* Desktop View - Scrollable Tabs */}
                    <Box sx={{ display: { xs: 'none', md: 'block' } }}>
                        <Tabs
                            value={value}
                            onChange={handleChange}
                            variant="scrollable"
                            scrollButtons="auto"
                            sx={{
                                '& .MuiTabs-indicator': { display: 'none' },
                                '& .MuiTabs-flexContainer': {
                                    gap: 1,
                                    position: 'relative',
                                    flexWrap: 'nowrap',
                                    justifyContent: 'center',
                                    border: 'none'
                                }
                            }}
                        >
                            {tabsData.map((tab, index) => (
                                <Tab
                                    key={index}
                                    sx={{
                                        minHeight: 'auto',
                                        minWidth: 'auto',
                                        alignItems: 'center',
                                        padding: '14px 16px',
                                        textTransform: 'none',
                                        borderRadius: '4px',
                                        border: `2px solid ${theme.palette.secondary.dark}`,
                                        backgroundColor: value === index ? theme.palette.text.primary : theme.palette.secondary.dark,
                                        '&:hover': {
                                            backgroundColor: theme.palette.text.primary,
                                            '& .MuiBox-root': {
                                                color: theme.palette.secondary.dark
                                            }
                                        },
                                        '& .MuiTab-wrapper': {
                                            flexDirection: 'row',
                                            alignItems: 'center',
                                            gap: '8px'
                                        }
                                    }}
                                    label={
                                        <Box
                                            sx={{
                                                display: 'flex',
                                                alignItems: 'center',
                                                gap: '8px',
                                                color: value === index ? theme.palette.primary.main : theme.palette.common.white,
                                                transition: 'all 0.3s ease'
                                            }}
                                        >
                                            {tab.icon}
                                            <Typography
                                                variant="body1"
                                                fontWeight={600}
                                                noWrap
                                                sx={{
                                                    display: 'inline-block',
                                                    maxWidth: '100%',
                                                    overflow: 'hidden',
                                                    textOverflow: 'ellipsis'
                                                }}
                                            >
                                                {tab.label}
                                            </Typography>
                                        </Box>
                                    }
                                />
                            ))}
                        </Tabs>
                    </Box>
                </Grid>
            </Grid>

            <TabSection1 title={tabsData[value].label2} description={tabsData[value].description} imageShow={false} />
        </>
    );
};

export default SimpleTab;
