import { useState } from 'react';
import { Box, Tabs, Tab, Typography, Grid } from '@mui/material';
import { useTheme, styled } from '@mui/material/styles';
import TabSection from '../sections/TabSection';

const CustomTabs = ({ tabsData, imageShow }) => {
    const theme = useTheme();
    const [value, setValue] = useState(0);

    const handleChange = (event, newValue) => {
        setValue(newValue);
    };

    // Styled Circular Tab
    const CircleTab = styled('div')(({ selected }) => ({
        width: 10,
        height: 10,
        borderRadius: '50%',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        backgroundColor: theme.palette.common.white,
        marginBottom: 8
    }));

    // Styled Tab Label
    const TabLabel = styled('div')(({ selected }) => ({
        color: theme.palette.common.white,
        textAlign: 'center',
        lineHeight: '1.3',
        whiteSpace: 'pre-line'
    }));

    return (
        <Grid container justifyContent="left">
            <Grid item xs={12}>
                <Box sx={{ position: 'relative', paddingBottom: '2px' }}>
                    {/* Mobile View - Grid Layout */}
                    <Box sx={{ display: { xs: 'flex', md: 'none' }, flexWrap: 'wrap', gap: 1 }}>
                        {tabsData.map((tab, index) => (
                            <Box
                                key={index}
                                onClick={() => setValue(index)}
                                sx={{
                                    width: 'calc(50% - 8px)',
                                    minHeight: 'auto',
                                    padding: '12px',
                                    textTransform: 'none',
                                    borderRadius: '8px',
                                    backgroundColor: value === index ? theme.palette.secondary.dark : 'transparent',
                                    display: 'flex',
                                    flexDirection: 'column',
                                    alignItems: 'center',
                                    cursor: 'pointer'
                                }}
                            >
                                <CircleTab
                                    selected={value === index}
                                    sx={{
                                        padding: { xs: '1.5rem', sm: '2rem' }, // Adjusted padding for mobile
                                        marginBottom: { xs: '4px', sm: '8px' }, // Adjusted margin for mobile
                                        color: theme.palette.secondary.dark
                                    }}
                                >
                                    {tab.icon}
                                </CircleTab>
                                <TabLabel selected={value === index}>
                                    <Typography variant="body1" fontWeight={600} fontSize={{ xs: '0.875rem', sm: '1rem' }}>
                                        {tab.label}
                                    </Typography>
                                </TabLabel>
                            </Box>
                        ))}
                    </Box>

                    {/* Desktop View - Tabs */}
                    <Box sx={{ display: { xs: 'none', md: 'block' } }}>
                        <Tabs
                            value={value}
                            onChange={handleChange}
                            variant="scrollable"
                            scrollButtons="auto"
                            sx={{
                                '& .MuiTabs-flexContainer': {
                                    gap: 1,
                                    position: 'relative',
                                    borderBottom: 'none' // Remove bottom border container
                                }
                            }}
                        >
                            {tabsData.map((tab, index) => (
                                <Tab
                                    key={index}
                                    sx={{
                                        minHeight: 'auto',
                                        padding: '12px',
                                        textTransform: 'none',
                                        borderRadius: '8px',
                                        backgroundColor: value === index ? theme.palette.secondary.dark : 'transparent',
                                        '& .MuiTab-wrapper': {
                                            flexDirection: 'column',
                                            alignItems: 'center'
                                        }
                                    }}
                                    icon={
                                        <CircleTab
                                            sx={{
                                                padding: '2.5rem',
                                                color: theme.palette.secondary.dark
                                            }}
                                            selected={value === index}
                                        >
                                            {tab.icon}
                                        </CircleTab>
                                    }
                                    label={
                                        <TabLabel selected={value === index}>
                                            <Typography variant="body1" fontWeight={600}>
                                                {tab.label}
                                            </Typography>
                                        </TabLabel>
                                    }
                                />
                            ))}
                        </Tabs>
                    </Box>
                </Box>

                <TabSection title={tabsData[value].label} description={tabsData[value].description} imageShow={false} />
            </Grid>
        </Grid>
    );
};

export default CustomTabs;
