import { Grid, Typography, Box } from '@mui/material';
import { useTheme } from '@mui/material/styles';

const ContentBlock = ({
    title,
    titleParts = [],
    paragraphLine1,
    paragraphLine2,
    align = 'center',
    maxWidth = { xs: '90%', sm: '80%', md: '90%' },
    color = 'secondary',
    pracolor = 'primary',
    bold = 400
}) => {
    const theme = useTheme();
    const titleColor = theme.palette.text[color] || theme.palette.text.secondary;
    const paragraphColor = theme.palette.text[pracolor] || theme.palette.text.primary;
    const renderTitle = (bold) => {
        if (titleParts.length > 0) {
            return (
                <Box component="span" sx={{ display: 'inline-block' }}>
                    {titleParts.map((part, index) => (
                        <Typography
                            key={index}
                            component="span"
                            sx={{
                                fontSize: { xs: '1.8rem', sm: '2rem', md: '3.5rem' },
                                fontWeight: 900,
                                lineHeight: 1.3,
                                color: part.color || titleColor,
                                display: 'inline',
                                wordBreak: 'break-word',
                                textAlign: { xs: 'center', md: align }
                            }}
                        >
                            {part.text}
                        </Typography>
                    ))}
                </Box>
            );
        }
        return title;
    };

    return (
        <Grid item xs={12}>
            <Grid container spacing={2} sx={{ mb: 2, padding: { xs: '0.5rem', sm: '1rem' } }}>
                <Grid item xs={12}>
                    <Typography
                        variant="h1"
                        component="div"
                        sx={{
                            fontSize: { xs: '1.8rem', sm: '1.5rem', md: '2.5rem' },
                            fontWeight: bold,
                            lineHeight: 1.3,
                            textAlign: { xs: 'center', md: align },
                            color: titleColor,
                            wordBreak: 'break-word',
                            px: { xs: 1, sm: 0 }
                        }}
                    >
                        {renderTitle(bold)}
                    </Typography>
                </Grid>

                {(paragraphLine1 || paragraphLine2) && (
                    <Grid item xs={12}>
                        <Box
                            sx={{
                                maxWidth,
                                margin: align === 'center' ? '0 auto' : '0',
                                px: { xs: 1, sm: 0 }
                            }}
                        >
                            {paragraphLine1 && (
                                <Typography
                                    variant="body2"
                                    component="div"
                                    sx={{
                                        fontSize: { xs: '1rem', sm: '1rem', md: '1.2rem' },
                                        fontWeight: 300,
                                        lineHeight: 1.6,
                                        color: paragraphColor,
                                        textAlign: { xs: 'center', md: align },
                                        whiteSpace: 'pre-line'
                                    }}
                                >
                                    {paragraphLine1}
                                </Typography>
                            )}

                            {paragraphLine2 && (
                                <Typography
                                    variant="body2"
                                    component="div"
                                    sx={{
                                        fontSize: { xs: '1rem', sm: '1rem', md: '1.2rem' },
                                        fontWeight: 300,
                                        lineHeight: 1.6,
                                        color: paragraphColor,
                                        textAlign: { xs: 'center', md: align },
                                        mt: 1,
                                        whiteSpace: 'pre-line'
                                    }}
                                >
                                    {paragraphLine2}
                                </Typography>
                            )}
                        </Box>
                    </Grid>
                )}
            </Grid>
        </Grid>
    );
};

export default ContentBlock;
