import { Box, Grid, Avatar } from '@mui/material';
import { styled, useTheme } from '@mui/material/styles';
import { motion, useAnimation } from 'framer-motion';
import { useInView } from 'react-intersection-observer';
import { useEffect } from 'react';
import { SiBluesky } from 'react-icons/si';

// Responsive Diamond Styles
const diamondStyles = (theme) => ({
    width: { xs: 80, sm: 100, md: 120 },
    height: { xs: 80, sm: 100, md: 120 },
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    position: 'relative',
    border: `2px solid ${theme.palette.primary.main}`,
    transition: 'transform 0.3s ease, box-shadow 0.3s ease',
    backdropFilter: 'blur(10px)'
});

// Styled Wrapper with responsive padding
const IconGridWrapper = styled(Box)(({ theme }) => ({
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    width: '100%',
    padding: theme.spacing(4, 0, 8, 0),
    [theme.breakpoints.down('sm')]: {
        padding: theme.spacing(3, 0, 6, 0)
    }
}));

// Social Media Data with brand colors
const socialIcons = [
    { id: 1, name: 'Facebook', bgColor: '#1877F2', icon: <i className="fab fa-facebook-f fa-2x" /> },
    { id: 2, name: 'Twitter', bgColor: '#000000', icon: <i className="fab fa-twitter fa-2x" /> },
    {
        id: 3,
        name: 'Instagram',
        bgColor: 'linear-gradient(45deg, #405DE6, #5851DB, #833AB4, #C13584, #E1306C, #FD1D1D, #F56040, #F77737, #FCAF45, #FFDC80)',
        icon: <i className="fab fa-instagram fa-2x" />
    },
    { id: 4, name: 'YouTube', bgColor: '#FF0000', icon: <i className="fab fa-youtube fa-2x" /> },
    { id: 5, name: 'TikTok', bgColor: '#000000', icon: <i className="fab fa-tiktok fa-2x" /> },
    { id: 6, name: 'LinkedIn', bgColor: '#0077B5', icon: <i className="fab fa-linkedin-in fa-2x" /> },
    {
        id: 7,
        name: 'WordPress',
        bgColor: '#21759B', // Official WordPress brand color
        icon: <i className="fab fa-wordpress fa-2x" />
    },
    { id: 8, name: 'Bluesky', bgColor: '#0085FF', icon: <SiBluesky size={32} color="white" /> }
];

const DiamondSocialMediaIcons = () => {
    const theme = useTheme();
    const controls = useAnimation();
    const [ref, inView] = useInView({ threshold: 0.1 });

    // Animation variants
    const cardVariants = {
        hidden: { opacity: 0, scale: 0.8, rotate: 45 },
        visible: { opacity: 1, scale: 1, rotate: 45, transition: { duration: 0.5, ease: 'easeOut' } }
    };

    useEffect(() => {
        if (inView) {
            controls.start((i) => ({
                opacity: 1,
                scale: 1,
                rotate: 45,
                transition: { delay: i * 0.15, duration: 0.5, ease: 'easeOut' }
            }));
        } else {
            controls.set({ opacity: 0, scale: 0.8, rotate: 45 });
        }
    }, [controls, inView]);

    const MotionBox = motion(Box);

    return (
        <Grid container xs={12} ref={ref}>
            <IconGridWrapper>
                <Grid container spacing={{ xs: 1, sm: 3, md: 4 }} justifyContent="center">
                    {socialIcons?.map((social, index) => (
                        <Grid item key={social.id}>
                            <MotionBox
                                sx={diamondStyles(theme)}
                                custom={index}
                                initial="hidden"
                                animate={controls}
                                variants={cardVariants}
                                whileHover={{
                                    scale: 1.1,
                                    boxShadow: `0px 6px 20px ${theme.palette.primary.main}`
                                }}
                            >
                                <Avatar
                                    sx={{
                                        width: { xs: 40, sm: 60, md: 60 },
                                        height: { xs: 40, sm: 60, md: 60 },
                                        transform: 'rotate(-45deg)',
                                        background: social.bgColor,
                                        color: '#ffffff',
                                        boxShadow: '0px 3px 8px rgba(0, 0, 0, 0.2)',
                                        display: 'flex',
                                        justifyContent: 'center',
                                        alignItems: 'center',
                                        '& .MuiSvgIcon-root': {
                                            fontSize: { xs: '1.5rem', sm: '1.75rem', md: '2rem' }
                                        }
                                    }}
                                >
                                    {social.icon}
                                </Avatar>
                            </MotionBox>
                        </Grid>
                    ))}
                </Grid>
            </IconGridWrapper>
        </Grid>
    );
};

export default DiamondSocialMediaIcons;
