import Slider from 'react-slick';
import { Card, CardContent, Typography, Box, Grid } from '@mui/material';
import { styled, useTheme } from '@mui/material/styles';

// Styled Slider Container
const SliderContainer = styled('div')(({ theme }) => ({
    width: '100%',
    padding: '0px',
    overflow: 'hidden',
    background: 'transparent',
    '& .slick-slide': {
        padding: '0 4px' // Consistent spacing between slides
    }
}));

// Styled Interactive Card
const StyledCard = styled(Card)(({ theme }) => ({
    background: theme.palette.text.primary,
    border: `2px solid ${theme.palette.secondary.main}`,
    borderRadius: '8px',
    color: theme.palette.secondary.main,
    transition: 'all 0.3s ease',
    display: 'inline-flex',
    margin: '5px 0', // Adjusted margin
    height: '60px',
    alignItems: 'center',
    justifyContent: 'center',
    minWidth: '195px',
    '& .MuiCardContent-root': {
        padding: '0 !important',
        whiteSpace: 'nowrap'
    }
}));

// Common slider settings with consistent spacing
const commonSettings = {
    infinite: true,
    centerMode: false, // Changed from true to false for consistent spacing
    slidesToShow: 6,
    autoplay: true,
    speed: 6000,
    autoplaySpeed: 0,
    cssEase: 'linear',
    arrows: false,
    responsive: [
        {
            breakpoint: 1024,
            settings: {
                slidesToShow: 5
            }
        },
        {
            breakpoint: 768,
            settings: {
                slidesToShow: 4
            }
        },
        {
            breakpoint: 600,
            settings: {
                slidesToShow: 2
            }
        },
        {
            breakpoint: 480,
            settings: {
                slidesToShow: 1.5 // Allows partial visibility of next slide
            }
        }
    ]
};

// First row moves left
const settingsLeft = { ...commonSettings, rtl: false };

// Second row moves right
const settingsRight = { ...commonSettings, rtl: true };

// Card data
const cards = [
    { id: 1, title: 'Spintax' },
    { id: 2, title: 'Watermark' },
    { id: 3, title: 'URL Shortener' },
    { id: 4, title: 'Save & Edit drafts' },
    { id: 5, title: 'Multiple Accounts' },
    { id: 6, title: 'Save & Get Captions' },
    { id: 7, title: 'Image & Video Library' },
    { id: 8, title: 'Integrate Scheduling Easily' }
];

const cards1 = [
    { id: 1, title: 'Account Manager' },
    { id: 2, title: 'Preview Post' },
    { id: 3, title: 'Optimize Results' },
    { id: 4, title: 'OpenAI' },
    { id: 5, title: 'Auto reposting' },
    { id: 6, title: 'Group Manager' },
    { id: 7, title: 'Support Media,Links & Text' }
];

const isSingleWord = (text) => text.trim().split(/\s+/).length === 1;

const TwoRowSlides = () => {
    const theme = useTheme();
    return (
        <Grid item xs={12} lg={12} md={12}>
            <SliderContainer>
                {/* First Row - Moves Left */}
                <Slider {...settingsLeft}>
                    {cards.map((card) => (
                        <Box key={card.id}>
                            <StyledCard
                                sx={{
                                    padding: isSingleWord(card.title) ? '20px 40px' : '20px 4px'
                                }}
                            >
                                <CardContent>
                                    <Typography
                                        variant="body1"
                                        sx={{
                                            fontSize: '0.98rem',
                                            fontWeight: 500,
                                            whiteSpace: 'nowrap'
                                        }}
                                    >
                                        {card.title}
                                    </Typography>
                                </CardContent>
                            </StyledCard>
                        </Box>
                    ))}
                </Slider>

                {/* Second Row - Moves Right */}
                <Slider {...settingsRight}>
                    {cards1.map((card) => (
                        <Box key={card.id}>
                            <StyledCard
                                sx={{
                                    padding: isSingleWord(card.title) ? '18px 38px' : '20px 4px'
                                }}
                            >
                                <CardContent>
                                    <Typography
                                        variant="body1"
                                        sx={{
                                            fontSize: '0.98rem',
                                            fontWeight: 500,
                                            whiteSpace: 'nowrap'
                                        }}
                                    >
                                        {card.title}
                                    </Typography>
                                </CardContent>
                            </StyledCard>
                        </Box>
                    ))}
                </Slider>
            </SliderContainer>
        </Grid>
    );
};

export default TwoRowSlides;
