import { Container, Grid, Typography } from '@mui/material';
import { styled, useTheme } from '@mui/material/styles';
import { motion, useAnimation } from 'framer-motion';
import { useInView } from 'react-intersection-observer';
import { useEffect } from 'react';

// Styled Wrapper with animation capabilities
const SectionWrapper = styled(motion.div)(({ theme }) => ({
    padding: '80px 0',
    backgroundColor: '#E8F7F3',
    borderRadius: '18px', // Add rounded corners
    boxShadow: theme.shadows[4], // Use theme shadow
    [theme.breakpoints.down('lg')]: {
        padding: '10px 0',
        boxShadow: theme.shadows[2]
    }
}));

// Responsive Image
const SectionImage = styled(motion.img)(({ theme }) => ({
    width: '100%',
    maxWidth: 700,
    height: 'auto',
    objectFit: 'cover',
    borderRadius: '18px', // Add rounded corners
    animation: '5s wings ease-in-out infinite',
    [theme.breakpoints.down('md')]: {
        height: 300,
        margin: '20px 0'
    }
}));

// Animated Content Box
const ContentBox = styled(motion.div)(({ theme }) => ({
    color: theme.palette.text.dark,
    padding: '20px',
    textAlign: 'left',
    minHeight: 400,
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
    alignItems: 'left',
    transition: 'transform 0.3s ease, box-shadow 0.3s ease',
    [theme.breakpoints.down('md')]: {
        padding: '20px 0',
        minHeight: 'auto',
        textAlign: 'center'
    }
}));

const ImageTextSection = ({ imageSrc, title, description, isRight = false }) => {
    const theme = useTheme();
    const controls = useAnimation();
    const [ref, inView] = useInView({
        threshold: 0.2,
        triggerOnce: false
    });

    // Animation variants
    const containerVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: {
            opacity: 1,
            y: 0,
            transition: {
                duration: 0.6,
                ease: 'easeOut'
            }
        }
    };

    const imageVariants = {
        hidden: { opacity: 0, x: isRight ? 50 : -50 },
        visible: {
            opacity: 1,
            x: 0,
            transition: {
                duration: 0.8,
                ease: 'easeOut',
                delay: 0.2
            }
        }
    };

    const contentVariants = {
        hidden: { opacity: 0, y: 30 },
        visible: {
            opacity: 1,
            y: 0,
            transition: {
                duration: 0.6,
                ease: 'easeOut',
                delay: 0.4
            }
        }
    };

    useEffect(() => {
        if (inView) {
            controls.start('visible');
        } else {
            controls.start('hidden');
        }
    }, [controls, inView]);

    return (
        <SectionWrapper ref={ref} initial="hidden" animate={controls} variants={containerVariants}>
            <Container>
                <Grid container alignItems="center" spacing={0}>
                    {/* Image Section - Now visible on mobile */}
                    <Grid
                        item
                        xs={12}
                        md={6}
                        sx={{
                            display: 'flex',
                            justifyContent: 'center',
                            order: { xs: 1, md: isRight ? 2 : 1 },
                            p: 4, // Add padding around the image,
                            boxShadow: theme.shadows[6]
                        }}
                    >
                        <SectionImage src={imageSrc} alt={title} variants={imageVariants} whileHover={{ scale: 1.02 }} />
                    </Grid>

                    {/* Content Section */}
                    <Grid
                        item
                        xs={12}
                        md={6}
                        sx={{
                            order: { xs: 2, md: isRight ? 1 : 2 }
                        }}
                    >
                        <ContentBox variants={contentVariants} whileHover={{ scale: 1.03 }}>
                            <Typography
                                variant="body1"
                                sx={{
                                    fontWeight: 400,
                                    fontSize: { xs: '1.5rem', md: '2rem' },
                                    mb: 2,
                                    padding: { xs: '0', md: '0 1rem' },
                                    transition: 'color 0.3s ease'
                                }}
                            >
                                {title}
                            </Typography>
                            <Typography
                                variant="body1"
                                sx={{
                                    fontSize: { xs: '0.9rem', md: '1rem' },
                                    lineHeight: 1.6,
                                    fontWeight: 100,
                                    padding: { xs: '0', md: '0 1rem' },
                                    transition: 'opacity 0.3s ease'
                                }}
                            >
                                {description}
                            </Typography>
                        </ContentBox>
                    </Grid>
                </Grid>
            </Container>
        </SectionWrapper>
    );
};

export default ImageTextSection;
